from __future__ import annotations
from datetime import datetime, timezone
from sqlalchemy import String,Integer,Float,DateTime,ForeignKey,Text,Boolean
from sqlalchemy.orm import Mapped,mapped_column
from .db import Base

class TenantMixin:
    tenant_id:Mapped[str]=mapped_column(String(64),index=True)
class IdMixin:
    id:Mapped[int]=mapped_column(Integer,primary_key=True,autoincrement=True)
class TimestampMixin:
    created_at:Mapped[datetime]=mapped_column(DateTime,default=lambda: datetime.now(timezone.utc))

class Organization(Base,IdMixin,TimestampMixin): __tablename__='organizations'; name:Mapped[str]=mapped_column(String(160)); slug:Mapped[str]=mapped_column(String(80),unique=True)
class Site(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='sites'; name:Mapped[str]=mapped_column(String(160)); location:Mapped[str]=mapped_column(String(220),default='')
class ProductionLine(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='production_lines'; site_id:Mapped[int]=mapped_column(ForeignKey('sites.id')); name:Mapped[str]=mapped_column(String(160)); status:Mapped[str]=mapped_column(String(32),default='active')
class InspectionStation(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='inspection_stations'; line_id:Mapped[int]=mapped_column(ForeignKey('production_lines.id')); name:Mapped[str]=mapped_column(String(160))
class Camera(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='cameras'; line_id:Mapped[int]=mapped_column(ForeignKey('production_lines.id')); name:Mapped[str]=mapped_column(String(160)); source_uri:Mapped[str]=mapped_column(String(500),default='demo://conveyor'); status:Mapped[str]=mapped_column(String(32),default='healthy'); blur_score:Mapped[float]=mapped_column(Float,default=0)
class User(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='users'; email:Mapped[str]=mapped_column(String(255)); password_hash:Mapped[str]=mapped_column(String(255)); role:Mapped[str]=mapped_column(String(64),default='operator'); active:Mapped[bool]=mapped_column(Boolean,default=True)
class Shift(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='shifts'; name:Mapped[str]=mapped_column(String(80)); starts_at:Mapped[datetime]=mapped_column(DateTime); ends_at:Mapped[datetime]=mapped_column(DateTime)
class Batch(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='batches'; line_id:Mapped[int]=mapped_column(ForeignKey('production_lines.id')); code:Mapped[str]=mapped_column(String(100)); status:Mapped[str]=mapped_column(String(32),default='open'); purity_percent:Mapped[float]=mapped_column(Float,default=0)
class Product(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='products'; batch_id:Mapped[int]=mapped_column(ForeignKey('batches.id')); external_id:Mapped[str]=mapped_column(String(100)); decision:Mapped[str]=mapped_column(String(32),default='review')
class InspectionWorkflow(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='inspection_workflows'; name:Mapped[str]=mapped_column(String(160)); slug:Mapped[str]=mapped_column(String(100)); config_json:Mapped[str]=mapped_column(Text,default='{}')
class VisionModel(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='vision_models'; name:Mapped[str]=mapped_column(String(160)); task:Mapped[str]=mapped_column(String(100))
class ModelVersion(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='model_versions'; model_id:Mapped[int]=mapped_column(ForeignKey('vision_models.id')); version:Mapped[str]=mapped_column(String(32)); stage:Mapped[str]=mapped_column(String(32),default='development'); metrics_json:Mapped[str]=mapped_column(Text,default='{}'); artifact_uri:Mapped[str]=mapped_column(String(500),default='')
class InferenceJob(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='inference_jobs'; batch_id:Mapped[int|None]=mapped_column(ForeignKey('batches.id'),nullable=True); status:Mapped[str]=mapped_column(String(32),default='queued'); input_uri:Mapped[str]=mapped_column(String(500)); output_uri:Mapped[str]=mapped_column(String(500),default=''); metrics_json:Mapped[str]=mapped_column(Text,default='{}')
class TrackedObject(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='tracked_objects'; job_id:Mapped[int]=mapped_column(ForeignKey('inference_jobs.id')); track_key:Mapped[str]=mapped_column(String(100)); decision:Mapped[str]=mapped_column(String(32)); confidence:Mapped[float]=mapped_column(Float)
class Finding(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='findings'; job_id:Mapped[int]=mapped_column(ForeignKey('inference_jobs.id')); track_id:Mapped[int]=mapped_column(Integer); class_name:Mapped[str]=mapped_column(String(100)); confidence:Mapped[float]=mapped_column(Float); decision:Mapped[str]=mapped_column(String(32)); evidence_uri:Mapped[str]=mapped_column(String(500),default=''); review_status:Mapped[str]=mapped_column(String(32),default='pending')
class ReviewDecision(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='review_decisions'; finding_id:Mapped[int]=mapped_column(ForeignKey('findings.id')); reviewer:Mapped[str]=mapped_column(String(255)); decision:Mapped[str]=mapped_column(String(32)); notes:Mapped[str]=mapped_column(Text,default='')
class RejectEvent(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='reject_events'; finding_id:Mapped[int]=mapped_column(ForeignKey('findings.id')); protocol:Mapped[str]=mapped_column(String(32),default='mqtt'); payload_json:Mapped[str]=mapped_column(Text); acknowledged:Mapped[bool]=mapped_column(Boolean,default=True)
class PLCEvent(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='plc_events'; topic:Mapped[str]=mapped_column(String(255)); payload_json:Mapped[str]=mapped_column(Text); status:Mapped[str]=mapped_column(String(32),default='simulated')
class EvidenceImage(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='evidence_images'; finding_id:Mapped[int]=mapped_column(ForeignKey('findings.id')); uri:Mapped[str]=mapped_column(String(500)); sha256:Mapped[str]=mapped_column(String(64),default='')
class EvidenceClip(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='evidence_clips'; job_id:Mapped[int]=mapped_column(ForeignKey('inference_jobs.id')); uri:Mapped[str]=mapped_column(String(500)); sha256:Mapped[str]=mapped_column(String(64),default='')
class DatasetVersion(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='dataset_versions'; name:Mapped[str]=mapped_column(String(160)); version:Mapped[str]=mapped_column(String(50)); manifest_uri:Mapped[str]=mapped_column(String(500)); license:Mapped[str]=mapped_column(String(100))
class TrainingExperiment(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='training_experiments'; name:Mapped[str]=mapped_column(String(160)); status:Mapped[str]=mapped_column(String(32)); metrics_json:Mapped[str]=mapped_column(Text,default='{}')
class Deployment(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='deployments'; model_version_id:Mapped[int]=mapped_column(ForeignKey('model_versions.id')); target:Mapped[str]=mapped_column(String(100)); status:Mapped[str]=mapped_column(String(32),default='ready')
class DriftAlert(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='drift_alerts'; metric:Mapped[str]=mapped_column(String(100)); baseline:Mapped[float]=mapped_column(Float); current:Mapped[float]=mapped_column(Float); severity:Mapped[str]=mapped_column(String(32)); resolved:Mapped[bool]=mapped_column(Boolean,default=False)
class AuditEvent(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='audit_events'; actor:Mapped[str]=mapped_column(String(255)); action:Mapped[str]=mapped_column(String(160)); entity_type:Mapped[str]=mapped_column(String(100)); entity_id:Mapped[str]=mapped_column(String(100)); details_json:Mapped[str]=mapped_column(Text,default='{}')
class Report(Base,IdMixin,TenantMixin,TimestampMixin): __tablename__='reports'; report_type:Mapped[str]=mapped_column(String(100)); batch_id:Mapped[int|None]=mapped_column(ForeignKey('batches.id'),nullable=True); uri:Mapped[str]=mapped_column(String(500)); sha256:Mapped[str]=mapped_column(String(64),default='')
